            this.validateField(fieldName);
        }
    }

    validateField(fieldName) {
        const field = this.fields[fieldName];
        const value = field.element.value.trim();
        let error = '';

        if (fieldName === 'fullName') {
            if (!value) {
                error = 'Full name is required.';
            } else if (value.length < 2) {
                error = 'Full name must be at least 2 characters.';
            }
        }

        if (fieldName === 'email') {
            if (!value) {
                error = 'Email address is required.';
            } else if (!this.isValidEmail(value)) {
                error = 'Please enter a valid email address.';
            }
        }

        if (fieldName === 'phone') {
            if (value && !this.isValidPhone(value)) {
                error = 'Please enter a valid phone number.';
            }
        }

        this.updateFieldError(field, error);
    }

    updateFieldError(field, error) {
        if (error) {
            field.element.setAttribute('aria-invalid', 'true');
            field.errorElement.textContent = error;
        } else {
            field.element.setAttribute('aria-invalid', 'false');
            field.errorElement.textContent = '';
        }
    }

    isValidEmail(email) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    }

    isValidPhone(phone) {
        const phoneRegex = /^[\d\s\-+()]{10,}$/;
        return phoneRegex.test(phone);
    }

    validateForm() {
        let isValid = true;

        Object.keys(this.fields).forEach(fieldName => {
            this.fields[fieldName].touched = true;
            this.validateField(fieldName);

            const field = this.fields[fieldName];
            if (field.element.getAttribute('aria-invalid') === 'true') {
                isValid = false;
            }
        });

        if (!isValid) {
            const firstInvalidField = Object.values(this.fields).find(
                field => field.element.getAttribute('aria-invalid') === 'true'
            );
            if (firstInvalidField) {
                firstInvalidField.element.focus();
            }
        }

        return isValid;
    }

    handleSubmit(e) {
        e.preventDefault();

        if (!this.validateForm()) {
            return;
        }

        const formData = {
            fullName: this.fields.fullName.element.value.trim(),
            email: this.fields.email.element.value.trim(),
            phone: this.fields.phone.element.value.trim()
        };

        console.log('Form submitted with data:', formData);

        alert(`Thank you for contacting us, ${formData.fullName}! We'll get back to you at ${formData.email} soon.`);

        this.form.reset();
        Object.keys(this.fields).forEach(fieldName => {
            this.fields[fieldName].touched = false;
            this.updateFieldError(this.fields[fieldName], '');
        });
    }
}

